<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\View\View; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Http\RedirectResponse; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Models\Nest; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Dezerx\Subdomains\Subdomains; use Pterodactyl\Services\Dezerx\Subdomains\CloudflareClient; use Pterodactyl\Services\Dezerx\Subdomains\SubdomainManager; class SubdomainsController extends Controller { public function __construct( private readonly AlertsMessageBag $alert, private readonly CloudflareClient $cloudflare, private readonly SubdomainManager $manager, ) { } public function index(): View { $settings = Subdomains::all(); return view('admin.dezerx.subdomains.index', [ 'hasToken' => $settings['cloudflare_token'] !== '', 'maxPerServer' => $settings['max_per_server'], 'domains' => $this->domains(), 'nests' => Nest::query()->with('eggs')->get(), 'records' => $this->records(), ]); } public function settings(Request $request): RedirectResponse { $data = $request->validate([ 'cloudflare_token' => ['nullable', 'string', 'max:200'], 'max_per_server' => ['required', 'integer', 'between:0,25'], ]); Subdomains::save($data['cloudflare_token'] ?? null, (int) $data['max_per_server']); $this->alert->success('The subdomain settings have been saved.')->flash(); return redirect()->route('admin.dezerx.subdomains'); } public function clearToken(): RedirectResponse { Subdomains::clearToken(); $this->alert->success('The Cloudflare token has been removed. The tab is hidden until another is set.')->flash(); return redirect()->route('admin.dezerx.subdomains'); } public function verify(): RedirectResponse { $result = $this->cloudflare->verify(); $result['ok'] ? $this->alert->success('Cloudflare says: ' . $result['message'])->flash() : $this->alert->danger('Cloudflare says: ' . $result['message'])->flash(); return redirect()->route('admin.dezerx.subdomains'); } public function storeDomain(Request $request): RedirectResponse { $data = $this->validateDomain($request); if (DB::table('dezerx_subdomain_domains')->where('domain', $data['domain'])->exists()) { $this->alert->danger('That domain is already here.')->flash(); return redirect()->route('admin.dezerx.subdomains'); } $zone = $this->cloudflare->zoneId($data['domain']); DB::table('dezerx_subdomain_domains')->insert([ ...$data, 'zone_id' => $zone, 'created_at' => now(), 'updated_at' => now(), ]); $zone === null ? $this->alert->warning($data['domain'] . ' was added, but Cloudflare did not return a zone for it. Check the token reaches that zone.')->flash() : $this->alert->success($data['domain'] . ' was added.')->flash(); return redirect()->route('admin.dezerx.subdomains'); } public function updateDomain(Request $request, int $domain): RedirectResponse { $data = $this->validateDomain($request); if (!DB::table('dezerx_subdomain_domains')->where('id', $domain)->exists()) { $this->alert->danger('That domain is not here.')->flash(); return redirect()->route('admin.dezerx.subdomains'); } DB::table('dezerx_subdomain_domains')->where('id', $domain)->update([ ...$data, 'zone_id' => $this->cloudflare->zoneId($data['domain']), 'updated_at' => now(), ]); $this->alert->success('That domain has been updated.')->flash(); return redirect()->route('admin.dezerx.subdomains'); } public function destroyDomain(int $domain): RedirectResponse { DB::table('dezerx_subdomain_domains')->where('id', $domain)->delete(); $this->alert->success('That domain has been removed. Any DNS records it made are still at Cloudflare.')->flash(); return redirect()->route('admin.dezerx.subdomains'); } public function destroyRecord(int $record): RedirectResponse { $result = $this->manager->release($record); $result['ok'] ? $this->alert->success('That name has been released.')->flash() : $this->alert->danger($result['message'])->flash(); return redirect()->route('admin.dezerx.subdomains'); } private function validateDomain(Request $request): array { $data = $request->validate([ 'domain' => ['required', 'string', 'max:100', 'regex:/^[a-z0-9.-]+\.[a-z]{2,}$/i'], 'record_type' => ['required', 'string', 'in:SRV,CNAME'], 'protocol' => ['nullable', 'string', 'regex:/^_?[a-z0-9-]{0,20}$/i'], 'transport' => ['nullable', 'string', 'in:tcp,udp'], 'enabled' => ['nullable', 'boolean'], 'eggs' => ['nullable', 'array'], 'eggs.*' => ['integer', 'exists:eggs,id'], ]); $eggs = array_values(array_unique(array_map('intval', $data['eggs'] ?? []))); return [ 'domain' => strtolower(trim($data['domain'])), 'record_type' => strtoupper($data['record_type']), 'protocol' => trim((string) ($data['protocol'] ?? '')) ?: '_minecraft', 'transport' => $data['transport'] ?? 'tcp', 'enabled' => (bool) ($data['enabled'] ?? false), 'eggs' => $eggs === [] ? null : json_encode($eggs), ]; } private function domains(): array { return DB::table('dezerx_subdomain_domains')->orderBy('domain')->get()->all(); } private function records(): array { return DB::table('dezerx_subdomain_records as r') ->leftJoin('dezerx_subdomain_domains as d', 'd.id', '=', 'r.domain_id') ->leftJoin('users as u', 'u.id', '=', 'r.user_id') ->leftJoin('servers as s', 's.id', '=', 'r.server_id') ->orderByDesc('r.created_at') ->limit(500) ->get([ 'r.id', 'r.subdomain', 'r.record_type', 'r.target', 'r.port', 'r.created_at', 'd.domain', 'u.email', 's.name as server_name', 's.uuidShort as server_short', ]) ->all(); } } 